import React from "react";
import './Home.css';
import { Container,Card,Button } from "react-bootstrap";

const Home = () => {
    // this is my creativity insted of using divs i used map 
  const concerts = [
    {
      id: 1,
      date: "JULY 16",
      place: "DELHI",
      location: "BATRA THEATER"
    },
    {
      id: 2,
      date: "JULY 20",
      place: "GHAZIABAD",
      location: "OPULANT MALL"
    },
    {
      id: 3,
      date: "JULY 24",
      place: "LUCKNOW",
      location: "CHAR BAGH THEATER"
    },
    {
      id: 4,
      date: "AUG 5",
      place: "NOIDA",
      location: "GIP MALL"
    }
  ];

  const showConcert = concerts.map((item) => (
    <div key={item.id} className="concert-item">
      <div className="concert-date">
        <span>{item.date}</span>
      </div>
      <div className="concert-place">
        <span>{item.place}</span>
      </div>
      <div className="concert-location">
        <span>{item.location}</span>
      </div>
      <div className="concert-button">
        <button>BUY TICKETS</button>
      </div>
     
      
    </div>
  ));

  const tourPackages = [
    { id: 1, title: "Europe Tour", price: 1500, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/europe.jpeg?raw=true" },
    { id: 2, title: "Asia Tour", price: 1200, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/asia.jpeg?raw=true" },
    { id: 3, title: "Africa Tour", price: 1800, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/africa.jpeg?raw=true" },
    { id: 4, title: "Australia Tour", price: 2000, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/australia.jpeg?raw=true" },
    { id: 5, title: "Antarctica Tour", price: 3000, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/antarctica.jpeg?raw=true" },
    { id: 6, title: "North America Tour", price: 2000, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/northamerica.jpeg?raw=true" },
    { id: 7, title: "South America Tour", price: 1500, imageUrl: "https://github.com/SigmaArun/Webtask/blob/main/southamerica.jpeg?raw=true" },
  ];

  const showTourPackages = tourPackages.map((item) => (
    <div key={item.id} className="col-md-6 col-lg-4 mb-4 d-flex justify-content-center">
      <Card style={{ width: "18rem" }}>
        <Card.Img variant="top" src={item.imageUrl} />
        <Card.Body className="text-center">
          <Card.Title>{item.title}</Card.Title>
          <Card.Text><span>{item.price}$</span></Card.Text>
          <Button variant="primary">Book Now</Button>
          <Button variant="secondary">More Details</Button>
        </Card.Body>
      </Card>
    </div>
  ));

  return (
    <>
    <Container>
      <div className="home">
        <div className="album-button">
          <button>Get our Latest Album</button>
        </div>
        <div className="play-button">
          <button>Play</button>
        </div>
      </div>

      <div className="tours-section">
        <h2>up</h2>
        {showConcert}
      </div>
      <section>
          <h2 className="text-center my-4">Continent Tour Packages</h2>
          <div className="row">{showTourPackages}</div>
        </section>
      </Container>
    </>
  );
};

export default Home;
